<?php require_once '../config/auth.php'; wajib_role(['admin','pengepul']); $role=$_SESSION['role'];$msg='';
if($role==='admin'&&isset($_POST['jual'])){$pid=(int)$_POST['id_pengepul'];$sid=(int)$_POST['id_sampah'];$berat=(float)$_POST['berat'];$s=mysqli_query($koneksi,"SELECT harga_per_kg,stok FROM sampah WHERE id_sampah=$sid");$d=mysqli_fetch_assoc($s);if($d&&$berat>0&&$berat<=(float)$d['stok']){$h=(float)$d['harga_per_kg'];$total=$berat*$h;$st=mysqli_prepare($koneksi,"INSERT INTO setor_pengepul(id_pengepul,id_sampah,berat,harga_per_kg,total) VALUES(?,?,?,?,?)");mysqli_stmt_bind_param($st,'iiddd',$pid,$sid,$berat,$h,$total);mysqli_stmt_execute($st);mysqli_query($koneksi,"UPDATE sampah SET stok=stok-$berat WHERE id_sampah=$sid");$msg='Penjualan ke pengepul berhasil dicatat.';}else{$msg='Stok tidak cukup atau data tidak valid.';}}
include '../config/header.php';?><h2>🚚 <?=$role==='admin'?'Jual Sampah ke Pengepul':'Beli Sampah'?></h2><?php if($msg):?><div class="alert alert-info"><?=$msg?></div><?php endif;?><?php if($role==='admin'):?><div class="card p-4 mb-4"><form method="post" class="row g-3"><div class="col-md-4"><label class="form-label">Pengepul</label><select name="id_pengepul" class="form-select" required><?php $q=mysqli_query($koneksi,"SELECT * FROM pengepul");while($p=mysqli_fetch_assoc($q)):?><option value="<?=$p['id_pengepul']?>"><?=htmlspecialchars($p['nama_pengepul'])?></option><?php endwhile;?></select></div><div class="col-md-4"><label class="form-label">Sampah</label><select name="id_sampah" class="form-select" required><?php $q=mysqli_query($koneksi,"SELECT * FROM sampah");while($s=mysqli_fetch_assoc($q)):?><option value="<?=$s['id_sampah']?>"><?=htmlspecialchars($s['nama_sampah'])?> (stok <?=$s['stok']?> kg)</option><?php endwhile;?></select></div><div class="col-md-4"><label class="form-label">Berat (kg)</label><input type="number" step="0.01" min="0.01" name="berat" class="form-control" required></div><div><button name="jual" class="btn btn-primary">Catat Penjualan</button></div></form></div><?php endif;?><div class="card p-4"><table class="table table-bordered"><tr><th>ID</th><th>Pengepul</th><th>Sampah</th><th>Berat</th><th>Total</th><th>Tanggal</th></tr><?php $q=mysqli_query($koneksi,"SELECT sp.*,p.nama_pengepul,s.nama_sampah FROM setor_pengepul sp JOIN pengepul p ON p.id_pengepul=sp.id_pengepul JOIN sampah s ON s.id_sampah=sp.id_sampah ORDER BY sp.id_setor DESC");while($d=mysqli_fetch_assoc($q)):?><tr><td><?=$d['id_setor']?></td><td><?=htmlspecialchars($d['nama_pengepul'])?></td><td><?=htmlspecialchars($d['nama_sampah'])?></td><td><?=$d['berat']?> kg</td><td>Rp <?=number_format($d['total'],0,',','.')?></td><td><?=$d['tanggal']?></td></tr><?php endwhile;?></table></div><?php include '../config/footer.php';
